window.NPC_CHUNK_20 = [{"name":"Immense Mandragora","cr":15,"xp":51200,"race":"Immense Mandragora","age_category":"Adult","alignment":"CE","size":"Gargantuan","type":"plant","init":7,"senses":["low-light vision"],"ac":18,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+3 Dex, +9 natural, -4 size","hp":232,"hd":"16d8+160","hd_value":16,"hp_mods":"fast healing 10","fort":20,"ref":10,"will":6,"immunities":["plant traits"],"resists":["acid 5","cold 5","electricity 10"],"weaknesses":["vulnerable to darkness"],"speed":[{"type":"burrow","speed":10},{"type":"climb","speed":40},{"type":"land","speed":40}],"melee":"2 vine whips +25 (2d8+17/19-20 plus poison), bite +25 (2d8+17)","space":"20 ft.","reach":"20 ft. (30 ft. with vine whips)","special_attacks":[{"type":"shriek"}],"strength":45,"dexterity":17,"constitution":30,"intelligence":8,"wisdom":13,"charisma":10,"baseatk":12,"cmb":33,"cmd":46,"feats":[{"feat":"Awesome Blow"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (vine whips)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":25},{"skill":"Fly","value":0},{"skill":"Perception","value":12},{"skill":"Stealth","value":0,"special":"+8 in heavy plant growth"}],"languages":["Common","Aklo"],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Vine whip-injury; save Fort DC 28; frequency 1/round for 6 rounds; effect confused for 1 round; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Shriek","kind":"Su","details":"Once per day, as a standard action, an immense mandragora can give voice to an unsettling shriek that sounds not unlike the cry of gargantuan baby. All creatures within 30 ft. of a shrieking immense mandragora must make a DC 25 Reflex save or take 15d6 points of sonic damage and a DC 25 Will save or become nauseated for 1d4 rounds. A successful Reflex save halves the sonic damage, while a successful Will save negates the nausea. This is a sonic, mind-affecting effect. The save DC is Constitution-based."},{"type":"Vulnerable to Darkness","kind":"Ex","details":"An immense mandragora in an area of darkness loses its fast healing and becomes slowed, as per the spell."}],"during_combat":"The mandragoras require the entire first round of combat to collect into their Gargantuan form. During this round, the immense mandragora cannot make attacks. Once it is fully formed, it uses Power Attack with every strike, and Awesome Blow against characters that are able to make large numbers of melee attacks trying to force the characters to take move actions to get back in range, thus minimizing the damage they do.","morale":"The immense mandragora fights to the death.","source":"AP 36"},{"name":"Winged Owlbear","cr":14,"xp":38400,"race":"Winged Owlbear","age_category":"Adult","alignment":"CN","size":"Gargantuan","type":"magical beast","init":4,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":28,"ac_touch":11,"ac_flat_footed":23,"ac_mods":"+4 Dex, +1 dodge, +17 natural, -4 size","hp":248,"hd":"16d10+160","hd_value":16,"fort":20,"ref":14,"will":8,"speed":[{"type":"fly","speed":50,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"2 claws +26 (2d6+14/19-20 plus grab), bite +26 (2d6+14)","space":"20 ft.","reach":"15 ft.","strength":39,"dexterity":18,"constitution":31,"intelligence":6,"wisdom":16,"charisma":14,"baseatk":16,"cmb":34,"cmd":49,"cmd_special":"53 vs. trip","feats":[{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Natural Armor (3)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":14}],"languages":["Sylvan (cannot speak)"],"during_combat":"The two winged owlbears rise up as one to attack anyone who intrudes on their territory. They have little interest in creatures on the ground unless a flying or climbing creature retreats to it.","morale":"The winged owlbears fight to the death.","source":"AP 36"},{"name":"The Knurly Witch","cr":16,"xp":76800,"race":"annis hag","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Gyronna","level":13}],"alignment":"CE","size":"Large","type":"monstrous humanoid","init":2,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":12,"ac_flat_footed":24,"ac_mods":"+5 armor, +2 Dex, +1 dodge, +10 natural, -1 size","hp":249,"hd":"7d10+13d8+153","hd_value":20,"fort":16,"ref":11,"will":20,"dr":"2/bludgeoning","sr":17,"speed":[{"type":"land","speed":40}],"melee":"2 claws +23 (1d6+7/19-20 plus grab), bite +22 (1d6+7)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"aura of madness","details":"DC 21, 13 rounds/day"},{"type":"channel negative energy","details":"4/day, DC 17, 7d6"},{"type":"destructive aura","details":"+6, 13 rounds/day"},{"type":"destructive smite","details":"+6, 8/day"},{"type":"rend","details":"2d6+10"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"vision of madness"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":13,"spellsprepared_concentration":18,"spellsprepared":[{"spell_level":7,"spell_slots":2,"spells":[{"spell":"insanity","type":"domain"},{"spell":"summon monster VII"}]},{"spell_level":6,"spell_slots":3,"spells":[{"spell":"harm","type":"domain"},{"spell":"heal"},{"spell":"word of recall"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"flame strike"},{"spell":"greater command"},{"spell":"shout","type":"domain"},{"spell":"summon monster V"},{"spell":"wall of stone"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"air walk"},{"spell":"confusion","type":"domain"},{"spell":"cure critical wounds"},{"spell":"divine power"},{"spell":"sending"},{"spell":"spell immunity"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"contagion"},{"spell":"cure serious wounds","count":2},{"spell":"dispel magic"},{"spell":"rage","type":"domain"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"cure moderate wounds","count":3},{"spell":"hold person"},{"spell":"spiritual weapon"},{"spell":"touch of idiocy","type":"domain"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds","count":4},{"spell":"lesser confusion","type":"domain"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"mending"},{"spell":"read magic"}]}],"spelldomains":"Destruction, Madness","strength":25,"dexterity":14,"constitution":22,"intelligence":11,"wisdom":20,"charisma":12,"baseatk":16,"cmb":24,"cmd":37,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Intimidate","value":16},{"skill":"Knowledge (religion)","value":15},{"skill":"Perception","value":28},{"skill":"Spellcraft","value":13}],"languages":["Common","Giant"],"gear":"+3 leather armor, scarab of protection (9 charges), strand of prayer beads (standard)","before_combat":"The Knurly Witch activates her bead of karma, then casts shield of faith and air walk as soon as she sees the PCs approach her home.","during_combat":"The Knurly Witch casts summon monster spells for the first 2 rounds of combat to liven up the battlefield, moving into the air above her home via air walk if she can before she begins casting. She uses her ranged spells as much as possible, but if melee becomes unavoidable, she casts divine power, activates her destructive aura, and attacks with tooth and claw (and periodic touch spells).","morale":"If reduced to fewer than 100 hit points, the Knurly Witch casts word of recall. As an \"adopted\" native of the First World, she can use this spell to retreat to her sanctuary-area K16 in the House at the Edge of Time. There, she seeks out Nyrissa to report her failure to defend the Knurly House and prepares as mentioned in area K16 to confront the PCs one last time.","source":"AP 36, Pathfinder RPG Bonus Bestiary 11"},{"name":"Ilthuliak","cr":17,"xp":102400,"race":"wyrm black dragon","gender":"Female","age_category":"Adult","alignment":"CE","size":"Huge","type":"dragon","sub_types":["water"],"init":-1,"senses":["blindsense 60 ft.","darkvision 120 ft.","dragon senses"],"auras":["frightful presence (330 ft., DC 31)"],"ac":48,"ac_touch":7,"ac_flat_footed":48,"ac_mods":"+4 armor, -1 Dex, +33 natural armor, +4 shield, -2 size","hp":324,"hd":"24d12+168","hd_value":24,"fort":21,"ref":13,"will":21,"defensive_abilities":["evasion"],"dr":"20/magic","immunities":["acid","dragon traits","magic paralysis and sleep"],"sr":28,"speed":[{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"land","speed":60},{"type":"swim","speed":60}],"melee":"bite +34 (2d8+18), 2 claws +34 (2d6+12), 2 wings +32 (1d8+6), tail slap +32 (2d6+18)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"acid pool"},{"type":"acidic bite"},{"type":"breath weapon","details":"100-ft. line of acid, 22d6 damage, DC 31"},{"type":"crush","details":"2d8+18, DC 31"}],"spell_like_abilities_caster_level":24,"spell_like_abilities_concentration":28,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness","details":"110-foot radius"},{"spell":"insect plague"},{"spell":"plant growth"}]},{"frequency":"1/day","spells":[{"spell":"corrupt water"}]}],"spellsknown_caster_level":13,"spellsknown_concentration":17,"spellsknown":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"acid fog"},{"spell":"flesh to stone"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"teleport"},{"spell":"transmute rock to mud"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"dimension door"},{"spell":"enervation"},{"spell":"hallucinatory terrain"},{"spell":"mass reduce person"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"clairaudience/clairvoyance"},{"spell":"dispel magic"},{"spell":"haste"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"acid arrow"},{"spell":"detect thoughts"},{"spell":"invisibility"},{"spell":"resist energy"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"ray of enfeeblement"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":35,"dexterity":8,"constitution":25,"intelligence":18,"wisdom":21,"charisma":18,"baseatk":24,"cmb":38,"cmd":47,"cmd_special":"51 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Eschew Materials"},{"feat":"Improved Bull Rush"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":31},{"skill":"Fly","value":22},{"skill":"Intimidate","value":31},{"skill":"Knowledge (arcana)","value":31},{"skill":"Knowledge (history)","value":31},{"skill":"Knowledge (planes)","value":31},{"skill":"Perception","value":32},{"skill":"Sense Motive","value":32},{"skill":"Stealth","value":18},{"skill":"Swim","value":39}],"languages":["Common","Aklo","Draconic","Skald","Sylvan"],"sq":["speak with reptiles","swamp stride","water breathing"],"gear":"ring of evasion","before_combat":"Ilthuliak casts mage armor, shield, and invisibility (in that order) on herself before she initiates combat. As a result, the dragon's AC increases to an impressive 48-this may be far too high for your PCs to handle, so if you are worried that the battle won't be fair, feel free to replace mage armor or shield with other 1st-level spells like magic missile and obscuring mist.","during_combat":"The dragon opens combat with her breath weapon, following up with a few rounds flying overhead and casting spells like acid fog, mass reduce person, and flesh to stone at PCs on the ground below. When her breath weapon recharges, she casts haste, then on the next round swoops down to land amid the PCs and uses her breath weapon again-on the following several rounds, she loses herself in the glory of melee battle, periodically taking to the sky to cast a few more spells.","morale":"Ilthuliak fights to the death.","source":"AP 36, Pathfinder RPG Bestiary 92"},{"name":"Tarlaxian","cr":18,"xp":153600,"race":"tarn linnorm \"runt\"","gender":"Male","age_category":"Adult","alignment":"CE","size":"Gargantuan","type":"dragon","sub_types":["aquatic"],"init":12,"senses":["all-around vision","darkvision 120 ft.","low-light vision","scent","true seeing"],"ac":35,"ac_touch":14,"ac_flat_footed":27,"ac_mods":"+8 Dex, +21 natural, -4 size","hp":279,"hd":"18d12+162","hd_value":18,"hp_mods":"regeneration 15 (cold iron)","fort":20,"ref":21,"will":18,"defensive_abilities":["freedom of movement"],"dr":"15/cold iron","immunities":["acid","curse effects","flanking","mind-affecting effects","paralysis","poison","sleep effects"],"sr":29,"speed":[{"type":"fly","speed":100,"maneuverability":"average"},{"type":"land","speed":40},{"type":"swim","speed":80}],"melee":"2 bites +26 (2d8+12/19-20 plus poison), 2 claws +26 (1d8+12), tail +21 (2d6+6 plus grab)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"breath weapon","details":"DC 28"},{"type":"constrict","details":"tail, 2d6+18"},{"type":"death curse","details":"DC 26"}],"strength":34,"dexterity":26,"constitution":28,"intelligence":7,"wisdom":25,"charisma":27,"baseatk":18,"cmb":34,"cmb_special":"+38 grapple","cmd":52,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bites)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":23},{"skill":"Perception","value":36},{"skill":"Stealth","value":17},{"skill":"Swim","value":41}],"languages":["Aklo","Draconic","Sylvan"],"sq":["amphibious","flight"],"special_abilities":[{"type":"Poison","kind":"Su","details":"Bite-injury; save Fort DC 28; frequency 1/round for 10 rounds; effect 4d6 acid damage and 1d6 Con drain; cure 3 consecutive saves. The save DC is Constitution-based."}],"during_combat":"Although small for a tarn linnorm, Tarlaxian is still rather enormous-if he notices anyone approaching the House, he bursts from the still waters of the lake to roar a challenge and then attacks.","morale":"Tarlaxian fights to the death.","source":"AP 36, Pathfinder RPG Bestiary 192"},{"name":"Ghostly Guard","cr":9,"xp":6400,"race":"elf","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":10}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented","elf","incorporeal"],"templates_applied":"ghost","init":7,"senses":["darkvision 60 ft.","low-light vision"],"ac":23,"ac_touch":19,"ac_flat_footed":19,"ac_mods":"+4 armor, +5 deflection, +3 Dex, +1 dodge","hp":115,"hd":"10d8+70","hd_value":10,"fort":8,"ref":12,"will":4,"save_mods":"+2 vs. enchantment","defensive_abilities":["channel resistance +4","improved evasion","improved uncanny dodge","incorporeal rejuvenation","trap sense +3"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"+1 ghost touch rapier +12 (1d6+3/18-20), corrupting touch +5 (11d6 [Fort DC 20 halves])","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"frightful moan","details":"DC 20"},{"type":"sneak attack +5d6 plus 5 bleed"},{"type":"telekinesis","details":"DC 20"}],"dexterity":17,"intelligence":14,"wisdom":13,"charisma":20,"baseatk":7,"cmb":7,"cmd":26,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Acrobatics","value":16,"special":"+4 jump"},{"skill":"Bluff","value":18},{"skill":"Disable Device","value":16},{"skill":"Fly","value":11},{"skill":"Intimidate","value":18},{"skill":"Knowledge (local)","value":15},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":14},{"skill":"Sleight of Hand","value":16},{"skill":"Stealth","value":24}],"sq":["rogue talents (bleeding attack +4, combat trick, improved evasion, surprise attack, weapon training)","trapfinding +5"],"gear":"+2 ghost touch leather armor, +1 ghost touch rapier","during_combat":"When these ghosts spot intruders, they use their frightful moan more as an alarm than an attack, then proceed to use telekinesis to attempt to disarm the intruders or hurl them against the walls of the House. After a few rounds, the ghosts swoop down to engage the PCs in melee-note that with their solid equipment, these ghosts cannot easily pass through walls.","morale":"The ghostly guards fight until destroyed.","source":"AP 36"},{"name":"The Wriggling Man","cr":18,"xp":153600,"race":"worm that walks","gender":"Male","age_category":"Adult","classes":[{"class":"transmuter","level":17}],"alignment":"NE","size":"Medium","type":"vermin","sub_types":["augmented humanoid"],"init":10,"senses":["all-around vision","blindsight 30 ft.","darkvision 60 ft."],"ac":34,"ac_touch":22,"ac_flat_footed":27,"ac_mods":"+6 armor, +2 deflection, +6 Dex, +1 dodge, +3 insight, +2 natural, +4 shield","hp":144,"hd":"17d6+85","hd_value":17,"hp_mods":"fast healing 18","fort":8,"ref":11,"will":13,"save_mods":"Will: +21 vs. mind-affecting","defensive_abilities":["worm that walks traits"],"dr":"15/-","immunities":["and sleep effects","disease","paralysis","poison"],"resists":["cold 30","fire 10"],"speed":[{"type":"fly","speed":60},{"type":"land","speed":30}],"melee":"swarm slam +14 (5d6 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"discorporate"},{"type":"engulf"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"change shape","details":"17 rounds/day, beast shape III/elemental body II"}]},{"frequency":"9/day","spells":[{"spell":"telekinetic fist +14 touch","details":"1d4+8"}]}],"spellsprepared_caster":"transmuter","spellsprepared_caster_level":17,"spellsprepared_concentration":23,"spellsprepared":[{"spell_level":9,"spell_slots":2,"spells":[{"spell":"summon monster IX"},{"spell":"time stop"}]},{"spell_level":8,"spell_slots":3,"spells":[{"spell":"mind blank"},{"spell":"polymorph any object"},{"spell":"quickened greater invisibility"}]},{"spell_level":7,"spell_slots":4,"spells":[{"spell":"mage's sword"},{"spell":"mass hold person"},{"spell":"quickened fireball"},{"spell":"reverse gravity"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"chain lightning"},{"spell":"disintegrate"},{"spell":"flesh to stone"},{"spell":"mage's lucubration"},{"spell":"quickened resist energy"},{"spell":"quickened scorching ray"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"feeblemind"},{"spell":"overland flight"},{"spell":"quickened shield"},{"spell":"telekinesis"},{"spell":"telepathic bond"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"black tentacles"},{"spell":"confusion"},{"spell":"dimension door"},{"spell":"mass reduce person"},{"spell":"mnemonic enhancer"},{"spell":"phantasmal killer"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic","count":2},{"spell":"fireball"},{"spell":"protection from energy"},{"spell":"slow"},{"spell":"stinking cloud"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"invisibility"},{"spell":"pyrotechnics"},{"spell":"resist energy"},{"spell":"scorching ray","count":3},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"expeditious retreat"},{"spell":"feather fall"},{"spell":"grease"},{"spell":"magic missile","count":3},{"spell":"reduce person"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"prohibited_schools":"Divination, Necromancy","strength":10,"dexterity":22,"constitution":16,"intelligence":22,"wisdom":16,"charisma":8,"baseatk":8,"cmb":8,"cmb_special":"+16 grapple","cmd":31,"feats":[{"feat":"Arcane Armor Training"},{"feat":"Combat Casting"},{"feat":"Combat Expertise"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Greater Spell Focus"},{"feat":"Improved Initiative"},{"feat":"Light Armor Proficiency"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (transmutation)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Fly","value":26},{"skill":"Knowledge (arcana)","value":26},{"skill":"Knowledge (local)","value":26},{"skill":"Knowledge (nobility)","value":26},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":28},{"skill":"Spellcraft","value":26},{"skill":"Stealth","value":31}],"languages":["Common","Abyssal","Aklo","Draconic","Sylvan","Terran","Undercommon"],"sq":["arcane bond (staff)","contingency","physical enhancement (Dex +4)","tenacious"],"special_abilities":[{"type":"Contingency","details":"If the Wriggling Man's hit points drop below 30, a dimension door activates."},{"type":"Discorporate","kind":"Su","details":"The Wriggling Man can collapse his body into a shapeless swarm of worms as a free action. He drops all held, worn, and carried items, and his Strength score changes to 1. He functions as a true swarm while discorporated, and has a reach of 0 ft. (his space remains unchanged). While discorporated, he loses all of his defensive abilities but gains all of the standard swarm traits. He also loses his slam attack and all special abilities and special attacks, but can make a swarm attack that inflicts 5d6 points of damage. He can reform into his true form as a full-round action, as long as he has at least 1 hit point-doing so provokes an attack of opportunity."},{"type":"Engulf","kind":"Ex","details":"If the Wriggling Man successfully grapples a foe, he can engulf that foe as soon as the attempt to grapple succeeds. He then sends a large number of the worms that comprise his body to swarm over the grappled creature. He can only engulf one target per round. These worms inflict 5d6 points of damage per round. The damage caused by an engulf attack is treated as swarm damage for the purposes of what creatures it can affect. Any creature damaged by this engulf attack is also subjected to distraction, and must make a DC 21 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based."},{"type":"Grab","kind":"Ex","details":"The Wriggling Man can use his grab attack on targets that are no more than one size category larger than himself."},{"type":"Tenacious","kind":"Ex","details":"The Wriggling Man gains a +8 racial bonus on CMB checks made to grapple a foe, rather than the normal +4 racial bonus granted to most creatures with the grab special attack. In addition, he gains a +4 racial bonus to his CMD. Worm That Walks Traits The Wriggling Man has no discernable anatomy, and isn't subject to critical hits or flanking. He can be damaged normally by weapons (such blows scattering worms or temporarily disrupting a portion of its body), but damage is mitigated normally by fast healing and damage reduction. Reducing him to 0 hit points forces him to discorporate-at 0 hit points he is staggered, and at negative hit points he is dying. He is immune to any spell or effect that targets a specific number of creatures (including single-target spells such as disintegrate), with the exception of such spells and effects generated by himself, which treat him as a single creature if he so chooses. Mind-affecting effects that target single creatures also function normally against him since his individual components share one hivemind in common. He takes half again as much damage (+50%) from spells or effects that affect an area, such as splash weapons and many evocation spells. The Wriggling Man is susceptible to high winds-treat him as a Fine creature for the purposes of determining the effects of wind."}],"gear":"+4 fire resistant leather armor, amulet of natural armor +2, headband of mental prowess +2 (Int [fly], Wis), ring of invisibility, ring of protection +2, portable hole (contains a small library, a reading desk, and all of his spellbooks-these books contain all of the wizard spells in the Pathfinder RPG Core Rulebook save for Divination and Necromancy spells), staff of transmutation","before_combat":"The Wriggling Man casts mind blank every day, and activates his ring of invisibility as soon as the PCs enter the House at the Edge of Time. He casts overland flight and resist energy (cold) once updates from Nyrissa convince him the PCs will soon be entering this room.","during_combat":"As soon as the PCs enter the room, the Wriggling Man, who stands near the throne but is invisible, casts time stop. He has at least 2 rounds to cast spells while time is stopped-he first casts quickened shield and then summon monster IX to summon an astral deva. The next round, he casts telepathic bond on the deva so he can communicate with it silently and quickened fire shield (chill shield) on himself. If he has enough time during time stop, he'll also cast quickened resist energy (acid) and protection from energy (sonic) on the third round, mage's sword on the fourth round, and reverse gravity on an area where he can affect the most walking PCs. When his time stop ends, he telepathically commands the summoned astral deva to imperiously demand that the PCs leave this place, claiming that they tread upon the works of one under the protection of Heaven itself. This is, of course, a lie-the Wriggling Man doesn't expect the PCs to fall for it, but the tactic does amuse him and it could work, especially if the PCs don't ask to make Sense Motive checks to see through the angel's forced lie. If the PCs persist, the Wriggling Man telepathically orders the angel to attack the PCs, starting with a blade barrier and following up with melee attacks with its hammer. The Wriggling Man keeps in motion, flying around the room invisibly as a move action after each time he casts an attack spell on the PCs each round so that it's difficult to track his position. The Wriggling Man tries to avoid melee combat if possible, but if his magic manages to incapacitate a character, he won't be able to resist approaching to engulf the poor PC.","morale":"If the Wriggling Man's contingency activates, he uses dimension door to retreat to area M6. He waits until he's recovered, then casts dimension door to return to this room to start the attack anew-this time he fights to the death.","source":"AP 36"},{"name":"Barbtongued Wyvern","cr":15,"xp":51200,"race":"wyvern","age_category":"Adult","alignment":"NE","size":"Huge","type":"dragon","templates_applied":"advanced","init":2,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":27,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+2 Dex, +1 dodge, +16 natural, -2 size","hp":250,"hd":"20d12+120","hd_value":20,"fort":18,"ref":14,"will":13,"immunities":["paralysis","sleep"],"speed":[{"type":"fly","speed":60,"maneuverability":"poor"},{"type":"land","speed":20}],"melee":"sting +26 (2d6+8 plus poison), bite +26 (4d6+8/19-20), 2 wings +21 (2d6+4), tongue +21 (1d4+4 plus grab)","space":"15 ft.","reach":"15 ft.; 30 ft. with tongue","special_attacks":[{"type":"pull","details":"tongue, 30 ft."},{"type":"rake","details":"2 talons +26, 1d8+8"}],"strength":27,"dexterity":14,"constitution":22,"intelligence":7,"wisdom":12,"charisma":9,"baseatk":20,"cmb":30,"cmd":43,"feats":[{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Improved Natural Attack (sting)"},{"feat":"Improved Natural Attack (wing)"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":17},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":24},{"skill":"Stealth","value":17}],"languages":["Draconic"],"during_combat":"If they can, the barbtongued wyverns start combat by swooping in to attack the PCs before the party can fully deploy into this room, limiting melee combat options while still being able to take advantage of their reach to strike at foes farther up the stairs or down a hall.","morale":"The barbtongued wyverns fight to the death.","source":"AP 36, Pathfinder RPG Bestiary 282, 294"},{"name":"Defaced Nymph","cr":10,"xp":9600,"race":"nymph","gender":"Female","age_category":"Adult","alignment":"CN","size":"Medium","type":"fey","templates_applied":"advanced, broken soul","init":5,"senses":["low-light vision"],"auras":["baleful gaze (DC 20)","blinding beauty (30 ft., DC 20)"],"ac":29,"ac_touch":25,"ac_flat_footed":23,"ac_mods":"+9 deflection, +5 Dex, +1 dodge, +4 natural","hp":108,"hd":"8d6+80","hd_value":8,"fort":11,"ref":11,"will":10,"dr":"10/cold iron, 5/-","resists":["acid 5","cold 5","electricity 5","fire 5","sonic 5"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":10}],"melee":"torturous touch +9 touch (2d6 plus 1d6 Dexterity plus convulsions)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"agonized wail"},{"type":"baleful gaze"},{"type":"stunning glance","details":"DC 20"},{"type":"torturous touch"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":7,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":4,"spell_slots":2,"spells":[{"spell":"air walk"},{"spell":"flame strike"}]},{"spell_level":3,"spell_slots":3,"spells":[{"spell":"call lightning"},{"spell":"poison"},{"spell":"spike growth"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"barkskin"},{"spell":"flame blade"},{"spell":"resist energy"},{"spell":"tree shape"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm animal"},{"spell":"endure elements"},{"spell":"entangle"},{"spell":"obscuring mist"},{"spell":"produce flame"}]},{"spell_level":0,"spell_slots":4,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"stabilize"}]}],"strength":16,"dexterity":21,"constitution":28,"intelligence":20,"wisdom":19,"charisma":23,"baseatk":4,"cmb":7,"cmd":32,"feats":[{"feat":"Combat Casting"},{"feat":"Diehard","type":"bonus"},{"feat":"Dodge"},{"feat":"Endurance","type":"bonus"},{"feat":"Mobility"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":16,"special":"+12 jump"},{"skill":"Bluff","value":17},{"skill":"Escape Artist","value":16},{"skill":"Intimidate","value":22},{"skill":"Knowledge (nature)","value":16},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":15},{"skill":"Perform (string)","value":17},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":16},{"skill":"Swim","value":22}],"languages":["Common","Aklo","Aquan","Draconic","Giant","Sylvan"],"special_abilities":[{"type":"Agonized Wail","kind":"Su","details":"As a standard action, a defaced nymph can emit an agonized wail that affects all creatures within 120 feet-this wail causes those who experience it to become shaken (Will DC 20 negates) as long as they remain within 120 ft. of the defaced nymph. A successful save renders a creature immune to that defaced nymph's agonized wail for 1 minute. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Baleful Gaze","kind":"Su","details":"Any creature within 60 ft. of a defaced nymph must succeed on a DC 20 Fortitude save or take 1d4 points of Strength, Constitution, and Charisma drain. Whatever the result of the saving throw, the creature cannot be affected by the same defaced nymph's baleful gaze again for 1 minute. The save DC is Charisma-based."},{"type":"Torturous Touch","kind":"Su","details":"A defaced nymph can make a touch attack to cause hideous, painful wounds to rip open in the target's body. This touch causes 2d6 points of slashing damage and 1d6 points of Dexterity damage, and causes the touched creature to fall prone in a fit of convulsions (during which the creature is helpless) for 1d4 rounds. A DC 20 Fortitude save negates the Dexterity damage and the convulsive fit. The save DC is Charisma-based."}],"before_combat":"If a defaced nymph has the opportunity before battle, she casts air walk and barkskin.","during_combat":"A defaced nymph uses her baleful gaze on the first round of combat, then activates her blinding beauty, saving her stunning glance to use against non-humanoid foes or creatures that manage to engage her in melee. She prefers to hang back and cast spells on foes, using her agonized wail if she's surrounded.","morale":"A defaced nymph fights to the death, as if eager for release from her painful existence.","source":"AP 36, Pathfinder RPG Bestiary 217, 294, Advanced Bestiary 34"},{"name":"Phomandala","cr":16,"xp":76800,"race":"medusa","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":12}],"alignment":"LE","size":"Medium","type":"monstrous humanoid","templates_applied":"saurian","init":5,"senses":["allaround vision","darkvision 60 ft.","low-light vision","scent"],"ac":32,"ac_touch":19,"ac_flat_footed":26,"ac_mods":"+4 armor, +3 deflection, +5 Dex, +1 dodge, +5 natural, +4 shield","hp":238,"hd":"8d10+12d6+152","hd_value":20,"fort":12,"ref":15,"will":17,"dr":"10/adamantine","speed":[{"type":"land","speed":30}],"melee":"3 bites +20 (1d8+7 plus poison), 2 claws +20 (1d4+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"laughing touch","details":"8/day"},{"type":"leaping pounce"},{"type":"petrifying gaze","details":"DC 21"},{"type":"poison","details":"DC 20"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":12,"spellsknown_concentration":17,"spellsknown":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"chain lightning"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"cone of cold"},{"spell":"nightmare"},{"spell":"tree stride"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"bestow curse"},{"spell":"dimension door"},{"spell":"poison"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"deep slumber"},{"spell":"displacement"},{"spell":"lightning bolt"},{"spell":"major image"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bull's strength"},{"spell":"cat's grace"},{"spell":"glitterdust"},{"spell":"hideous laughter"},{"spell":"scorching ray"},{"spell":"spectral hand"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"charm person"},{"spell":"disguise self"},{"spell":"entangle"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"bloodline":"Fey","strength":18,"dexterity":20,"constitution":22,"intelligence":10,"wisdom":16,"charisma":20,"baseatk":14,"cmb":18,"cmd":37,"feats":[{"feat":"Ability Focus (petrifying gaze)"},{"feat":"Arcane Strike"},{"feat":"Dodge"},{"feat":"Empower Spell"},{"feat":"Eschew Materials"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Quicken Spell"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":21,"special":"+8 jumping"},{"skill":"Perception","value":26},{"skill":"Spellcraft","value":23},{"skill":"Survival","value":11}],"languages":["Common"],"sq":["bloodline arcana","fleeting glance 12 rounds/day","woodland stride"],"special_abilities":[{"type":"Leaping Pounce","kind":"Ex","details":"When Phomandala charges a foe and jumps at least the last 10 ft. of it, she may make a full attack."}],"gear":"amulet of natural armor +3, ring of protection +3, 1,500 gp in diamond dust","before_combat":"Phomandala casts bull's strength, cat's grace, mage armor, stoneskin, spectral hand, and shield before combat begins if she has the time.","during_combat":"On the first round of combat, Phomandala uses spectral hand to make attacks with bestow curse, poison, and vampiric touch while attempting to stay at range-her woodland stride ability should make it easy for her to remain more mobile than the PCs in these tangled rooms, allowing her to make hit-and-run attacks.","morale":"Phomandala fights to the death.","source":"AP 36, Pathfinder RPG Bestiary 201, Advanced Bestiary 213"},{"name":"Nyrissa","cr":20,"xp":307200,"race":"nymph","gender":"Female","age_category":"Adult","classes":[{"class":"mystic theurge","level":10},{"class":"sorcerer","level":6}],"alignment":"CE","size":"Medium","type":"fey","init":14,"senses":["low-light vision"],"auras":["blinding beauty (DC 29)"],"ac":51,"ac_touch":34,"ac_flat_footed":40,"ac_mods":"+8 armor, +13 deflection, +10 Dex, +1 dodge, +5 natural, +4 shield","hp":378,"hd":"8d6+6d6+10d6+294","hd_value":24,"fort":32,"ref":35,"will":41,"defensive_abilities":["evasion","protection from decapitation"],"dr":"10/cold iron","sr":20,"speed":[{"type":"climb","speed":20},{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"flame blade +23 (1d8+8)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"laughing touch","details":"16/day"},{"type":"stunning glance","details":"DC 29"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":17,"spellsknown_concentration":30,"spellsknown":[{"spell_level":8,"spell_slots":5,"spells":[{"spell":"maze"}]},{"spell_level":7,"spell_slots":7,"spells":[{"spell":"greater teleport"},{"spell":"prismatic spray"}]},{"spell_level":6,"spell_slots":8,"spells":[{"spell":"chain lightning"},{"spell":"geas/ quest"},{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":9,"spells":[{"spell":"dismissal"},{"spell":"dominate person"},{"spell":"sending"},{"spell":"telekinesis"}]},{"spell_level":4,"spell_slots":9,"spells":[{"spell":"bestow curse"},{"spell":"charm monster"},{"spell":"dimension door"},{"spell":"greater invisibility"}]},{"spell_level":3,"spell_slots":9,"spells":[{"spell":"displacement"},{"spell":"haste"},{"spell":"lightning bolt"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":9,"spells":[{"spell":"detect thoughts"},{"spell":"glitterdust"},{"spell":"hideous laughter"},{"spell":"resist energy"},{"spell":"scorching ray"},{"spell":"spectral hand"}]},{"spell_level":1,"spell_slots":10,"spells":[{"spell":"charm person"},{"spell":"disguise self"},{"spell":"entangle"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"bloodline":"Fey","spellsprepared_caster":"druid","spellsprepared_caster_level":18,"spellsprepared_concentration":31,"spellsprepared":[{"spell_level":9,"spell_slots":2,"spells":[{"spell":"quickened cure critical wounds"},{"spell":"quickened death ward"}]},{"spell_level":8,"spell_slots":3,"spells":[{"spell":"finger of death"},{"spell":"quickened cure serious wounds"},{"spell":"reverse gravity"}]},{"spell_level":7,"spell_slots":5,"spells":[{"spell":"fire storm"},{"spell":"heal","count":2},{"spell":"quickened cure moderate wounds"},{"spell":"summon nature's ally VII"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"antilife shell"},{"spell":"greater dispel magic","count":2},{"spell":"summon nature's ally VI"},{"spell":"wall of stone","count":2}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"cure critical wounds","count":4},{"spell":"quickened cure light wounds"},{"spell":"wall of thorns"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"cure serious wounds","count":4},{"spell":"flame strike"},{"spell":"rusting grasp"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"cure moderate wounds","count":5},{"spell":"poison"},{"spell":"speak with plants"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"barkskin"},{"spell":"flame blade"},{"spell":"gust of wind"},{"spell":"lesser restoration","count":4}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds","count":5},{"spell":"produce flame"},{"spell":"speak with animals"}]},{"spell_level":0,"spell_slots":4,"spells":[{"spell":"create water"},{"spell":"guidance"},{"spell":"light"},{"spell":"stabilize"}]}],"strength":14,"dexterity":30,"constitution":32,"intelligence":22,"wisdom":32,"charisma":36,"baseatk":12,"cmb":22,"cmd":48,"feats":[{"feat":"Ability Focus (blinding beauty, stunning glance)"},{"feat":"Agile Maneuvers"},{"feat":"Combat Casting"},{"feat":"Craft Wondrous Item"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Extend Spell"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell"},{"feat":"Silent Spell"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":38},{"skill":"Bluff","value":41},{"skill":"Climb","value":10},{"skill":"Diplomacy","value":41},{"skill":"Fly","value":43},{"skill":"Knowledge (nature)","value":34},{"skill":"Knowledge (planes)","value":31},{"skill":"Perception","value":39},{"skill":"Sense Motive","value":23},{"skill":"Stealth","value":38},{"skill":"Swim","value":30}],"languages":["Common","Aklo","Draconic","Elven","Giant","Gnome","Hallit","Skald","Sylvan"],"sq":["bloodline arcana","contingency","inherent bonuses","inspiration","unearthly grace","wild empathy +21","woodland stride"],"special_abilities":[{"type":"Contingency","details":"If Nyrissa is brought below 0 hit points, a cure critical wounds spell heals her of 4d8+16 points of damage. Inherent Bonuses Nyrissa has used a manual of gainful exercise +4 and a tome of understanding +5 to increase her Constitution and her Wisdom. Protection from Decapitation Nyrissa has used a wish from a ring to gain a special defense against beheading-the first time she is beheaded by any effect (including a vorpal weapon), the wound immediately heals after it is dealt, effectively inflicts no damage, and doesn't decapitate her. A second decapitation effect inflicted before she can secure another wish to replenish this defense can kill her normally."}],"gear":"belt of physical perfection +6, bracers of armor +8, headband of mental superiority +6 (Acrobatics, Fly, Swim), ioun stones (orange prism, pale green prism), ring of evasion, ring of freedom of movement, scarab of protection (fully charged), wings of flying, fancy anklet worth 10,000 gp, 500 gp, rod of maximize metamagic","before_combat":"If she can, Nyrissa casts death ward, shield, barkskin, spectral hand, and flame blade before combat begins.","during_combat":"Nyrissa is a complex character with a huge number of choices in battle. She also has the advantage of being able to watch everything the PCs do in her home via the Fable. As a result, you should take the time to tailor Nyrissa's tactics to match the PCs' tactics as closely as possible. She begins most battles by casting antilife shell to prevent the PCs from approaching her if she can (although in the small confines of the Fable, she'll likely need to move up against a wall to make sure that the spell's emanation excludes the PCs when she casts it). She uses quickened spells to great effect, healing herself of damage or using them to cast spells like haste, displacement, or greater invisibility to bolster her defenses. If one of the PCs wields Briar, she focuses all of her attention on that PC, doing everything she can to defend herself from that PC and either defeat him or separate him from Briar. As an artifact, Briar is immune to dispel magic and damage, but that doesn't mean she can't use telekinesis to try to disarm it, dismissal on its wielder (only if the fight takes place on the First World), or (her favorite tactic) maze to keep that foe out of the battle (remember, though, that Briar grants SR 30 against her spells).","morale":"If Nyrissa is reduced to fewer than 100 hit points, she exits the Fable, then casts dimension door to reenter a different Fable portal long enough to use her magic to heal herself before she returns to area M7c to confront the PCs again. In the end, Nyrissa's madness and pride push her to the edge-she fights to the death.","source":"AP 36, Pathfinder RPG Bestiary 217"},{"name":"Choral the Conqueror","cr":25,"xp":1638400,"race":"great wyrm red dragon","age_category":"Adult","alignment":"CE","size":"Colossal","type":"dragon","sub_types":["fire"],"templates_applied":"advanced","init":4,"senses":["dragon sense","smoke vision"],"auras":["fire","frightful presence (360 ft., DC 32)"],"ac":43,"ac_touch":2,"ac_flat_footed":43,"ac_mods":"+41 natural, -8 size","hp":507,"hd":"29d12+319","hd_value":29,"fort":27,"ref":16,"will":26,"dr":"20/magic","immunities":["fire","paralysis","sleep"],"sr":36,"weaknesses":["vulnerability to cold"],"speed":[{"type":"fly","speed":250,"maneuverability":"clumsy"},{"type":"land","speed":40}],"melee":"bite +47 (4d8+27/19-20), 2 claws +47 (4d6+18), 2 wings +45 (2d8+9), tail slap +45 (4d6+27)","space":"30 ft.","reach":"25 ft. (30 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"70-ft. cone, DC 35, 24d10 fire"},{"type":"crush"},{"type":"incinerate"},{"type":"manipulate flames"},{"type":"melt stone"},{"type":"tail sweep"}],"spell_like_abilities_caster_level":29,"spell_like_abilities_concentration":37,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"discern location"},{"spell":"find the path"},{"spell":"pyrotechnics"},{"spell":"suggestion"},{"spell":"wall of fire"}]}],"spellsknown_caster_level":19,"spellsknown_concentration":27,"spellsknown":[{"spell_level":9,"spell_slots":4,"spells":[{"spell":"shapechange"},{"spell":"time stop"}]},{"spell_level":8,"spell_slots":7,"spells":[{"spell":"iron body"},{"spell":"polar ray"},{"spell":"polymorph any object"}]},{"spell_level":7,"spell_slots":7,"spells":[{"spell":"greater teleport"},{"spell":"limited wish"},{"spell":"spell turning"}]},{"spell_level":6,"spell_slots":7,"spells":[{"spell":"antimagic field"},{"spell":"contingency"},{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"polymorph"},{"spell":"telekinesis"},{"spell":"teleport"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"fear"},{"spell":"fire shield"},{"spell":"greater invisibility"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"haste"},{"spell":"tongues"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"alter self"},{"spell":"detect thoughts"},{"spell":"misdirection"},{"spell":"resist energy"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"grease"},{"spell":"magic missile"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"bleed"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":47,"dexterity":10,"constitution":33,"intelligence":26,"wisdom":27,"charisma":26,"baseatk":29,"cmb":55,"cmd":55,"cmd_special":"59 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Stunning Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Appraise","value":29},{"skill":"Bluff","value":29},{"skill":"Diplomacy","value":29},{"skill":"Fly","value":29},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":29},{"skill":"Knowledge (history)","value":29},{"skill":"Knowledge (local)","value":29},{"skill":"Knowledge (nobility)","value":29},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":29},{"skill":"Survival","value":29}],"languages":["Common","Abyssal","Draconic","Dwarven","Giant","Hallit","Ignan","Orc","Skald"],"source":"AP 36"},{"name":"Captain Avret Kinkarian","cr":3,"xp":800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"expert","level":2},{"class":"rogue","level":1}],"alignment":"CN","size":"Medium","type":"undead","sub_types":["augmented humanoid","human","incorporeal"],"templates_applied":"ghost","init":1,"senses":["darkvision 60 ft."],"ac":13,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 deflection, +1 Dex","hp":19,"hd":"3d8+6","hd_value":3,"fort":2,"ref":3,"will":4,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"weaknesses":["sea-bound"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +2 (3d6, Fort DC 13 half)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"dexterity":13,"intelligence":12,"wisdom":8,"charisma":14,"baseatk":1,"cmb":2,"cmd":14,"feats":[{"feat":"Alertness"},{"feat":"Iron Will"},{"feat":"Persuasive"}],"skills":[{"skill":"Climb","value":6},{"skill":"Diplomacy","value":10},{"skill":"Fly","value":9},{"skill":"Intimidate","value":10},{"skill":"Knowledge (geography)","value":7},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":15},{"skill":"Profession (sailor)","value":5},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":9},{"skill":"Swim","value":6}],"languages":["Common","Polyglot"],"sq":["trapfinding +1"],"special_abilities":[{"type":"Sea-Bound","kind":"Su","details":"Captain Kinkarian's ghost often appears to walk on water. He can leave the ocean's surface if he wishes, but each round he remains out of contact with the sea and takes more than a single move action, he takes 1d6 points of damage as his ghostly form drips and drains away, as if his very essence were being pulled back to the sea."}],"during_combat":"Captain Kinkarian attacks only in response to being attacked himself. In such a case, he sees his tormenters as his crew, and curses and froths at them for turning against him, issuing accusations of \"Mutineer!\" and \"Traitor!\" as he claws with his hook-handed corrupting touch. Faced with a woman who bears a passing resemblance to his lost love Aeshamara (any red-haired female Human, elf, or Half-Elf ), the ghost becomes fascinated and tearfully reaches toward that PC, whispering, \"Aeshamara... is that you? Have you come for me?\" The ghost remains fascinated for 1 round, after which he can he make a DC 20 Will save as a full-round action to recover from the fascination. Presenting the golden locket to him can also fascinate him in this manner. If anything attacks him, the fascination immediately ends. When he recovers from the fascination, he focuses his wrath on the woman he mistook for his love, shrieking, \"No... No! You are not her! Damnable harpy!\" If his enemies flee, Captain Kinkarian pursues until he loses sight of the sea, at which point he shrieks and returns to the surf to brood.","morale":"Captain Kinkarian fights until he's destroyed, but even then he merely rejuvenates back on the Brine Demon in 2d4 days. If the PCs have taken his locket for their own, he seeks them out again, following the lure of the locket unerringly-even across the ocean. In order to put Captain Kinkarian to rest, someone must forcefully present the open locket containing Aeshamara's image to the ghost so that he can see the image of the woman inside. This action causes the ghost to break off his attacks and reach for the locket-as soon as he touches it, his incorporeal form fades with a melancholy sigh as he finally meets his true death.","source":"AP 37, Pathfinder RPG Bestiary 144"},{"name":"Pezock","cr":2,"xp":600,"race":"tengu","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":3}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["tengu"],"init":7,"senses":["low-light vision"],"ac":15,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+1 armor, +3 Dex, +1 dodge","hp":23,"hd":"3d8+6","hd_value":3,"fort":2,"ref":6,"will":2,"defensive_abilities":["evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"+1 sawtooth sabre +6 (1d8+2/19-20), bite +0 (1d3) or crab slam -6 (2d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":13,"dexterity":17,"constitution":12,"intelligence":12,"wisdom":12,"charisma":8,"baseatk":2,"cmb":3,"cmd":17,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Craft (trapmaking)","value":7},{"skill":"Disable Device","value":9},{"skill":"Escape Artist","value":9},{"skill":"Knowledge (engineering)","value":4},{"skill":"Linguistics","value":5},{"skill":"Perception","value":9},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":11},{"skill":"Survival","value":4}],"languages":["Common","Polyglot","Tengu"],"sq":["gifted linguist","rogue talent (finesse rogue)","swordtrained","trapfinding +1"],"gear":"broken leather armor, +1 sawtooth sabre, broken dagger","during_combat":"Pezock sneak attacks the closest flat-footed foe he can on the first round of combat. If he has allies, he remains mobile and attempts to maximize his sneak attacks, but if on his own, the tengu prefers to take full attack actions-if facing multiple foes, he fights defensively.","morale":"Pezock attempts to flee if reduced to 10 hit points or fewer. He'll even drop his magic sword if he thinks that'll give him an extra few seconds to flee while his pursuer stops to pick the weapon up, but if he does so and gets away, he obsesses over getting his prize back.","source":"AP 37, Pathfinder RPG Bestiary 263"},{"name":"Vegepygmy Boss","cr":2,"xp":600,"race":"vegepygmy","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":1}],"alignment":"N","size":"Small","type":"plant","init":3,"senses":["darkvision 60 ft.","low-light vision"],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +3 natural, +1 size","hp":19,"hd":"1d8+1d10+10","hd_value":2,"fort":7,"ref":3,"will":0,"defensive_abilities":["plant traits"],"dr":"5/slashing or bludgeoning","immunities":["electricity"],"speed":[{"type":"land","speed":30}],"melee":"mwk longspear +5 (1d6+3/x3) or 2 claws +4 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":16,"constitution":16,"intelligence":10,"wisdom":11,"charisma":9,"baseatk":1,"cmb":2,"cmd":15,"feats":[{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":6},{"skill":"Perception","value":5},{"skill":"Stealth","value":15,"special":"+8 in vegetation"}],"languages":["Undercommon","Vegepygmy (cannot speak)"],"gear":"masterwork longspear","during_combat":"The boss, like the standard vegepygmies, prefers to capture living victims, and attempts to stabilize fallen foes so that it can try to feed them later in a hopeless attempt to grow more of its kind.","morale":"The vegepygmy boss fights to the death.","source":"AP 37, Pathfinder RPG Bestiary 273"},{"name":"Thrunefang Cannibal","cr":0.5,"xp":200,"race":"human","age_category":"Adult","classes":[{"class":"barbarian","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":11,"ac_touch":10,"ac_flat_footed":9,"ac_mods":"+2 Dex, -2 rage, +1 shield","hp":14,"hd":"1d12+8","hd_value":1,"fort":6,"ref":2,"will":3,"speed":[{"type":"land","speed":45}],"melee":"broken scimitar +3 (1d6+2)","ranged":"javelin +3 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"6 rounds/day"}],"strength":18,"dexterity":15,"constitution":19,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":1,"cmb":5,"cmd":15,"feats":[{"feat":"Fleet"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":7},{"skill":"Perception","value":5},{"skill":"Stealth","value":2},{"skill":"Survival","value":5},{"skill":"Swim","value":7}],"languages":["Pidgin Infernal"],"sq":["fast movement"],"gear":"light wooden shield, 3 javelins, broken scimitar, red pearl amulet worth 50 gp","during_combat":"The cannibals rage on the first round of combat and charge, if possible. They only use their javelins if they are unable to charge any foes or if an opponent is completely surrounded.","morale":"Fanatic and insane, the cannibals fight to the death if encountered in their camp. If encountered in the wilds, they flee if reduced below 5 hit points or if they run out of rounds of rage.","base_statistics":"AC 13, touch 12, flat-footed 11; hp 12; Fort +4, Will +1; Melee broken scimitar +1 (1d6+2); Str 14, Con 15; CMB +3; Skills Climb +5, Swim +5","source":"AP 37"},{"name":"Malikadna","cr":3,"xp":800,"race":"human","gender":"Female","age_category":"Old","classes":[{"class":"witch","level":4}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":13,"ac_touch":9,"ac_flat_footed":13,"ac_mods":"+4 armor, -1 Dex","hp":22,"hd":"4d6+8","hd_value":4,"fort":3,"ref":0,"will":7,"speed":[{"type":"land","speed":30}],"melee":"quarterstaff -1 (1d6-3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"cackle, evil eye, misfortune"}],"spellsprepared_caster":"witch","spellsprepared_caster_level":4,"spellsprepared_concentration":9,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"hideous laughter"},{"spell":"lesser restoration"},{"spell":"summon monster II"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"cause fear"},{"spell":"cure light wounds","count":2},{"spell":"mage armor"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":4,"spells":[{"spell":"dancing lights"},{"spell":"mending"},{"spell":"message"},{"spell":"touch of fatigue"}]}],"strength":5,"dexterity":9,"constitution":10,"intelligence":20,"wisdom":16,"charisma":12,"baseatk":2,"cmb":-1,"cmd":8,"feats":[{"feat":"Brew Potion"},{"feat":"Great Fortitude"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Bluff","value":5},{"skill":"Heal","value":10},{"skill":"Intimidate","value":8},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (religion)","value":9},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":5},{"skill":"Spellcraft","value":12}],"languages":["Common","Abyssal","Aklo","Infernal","Polyglot","Sylvan"],"sq":["witch's familiar (monkey named Thaltaki)"],"special_abilities":[{"type":"Cackle","kind":"Su","details":"As a move action that doesn't provoke an attack of opportunity, Malikadna can cackle madly. Any creature within 30 ft. that is under the effects of her evil eye or misfortune hex has the duration of that effect extended by 1 round."},{"type":"Evil Eye","kind":"Su","details":"As a standard action that doesn't provoke an attack of opportunity, Malikadna can use the evil eye to cause a visible foe within 30 ft. to take a -2 penalty on one of the following (Malikadna's choice): AC, ability checks, attack rolls, saving throws, or skill checks. This effect lasts for 8 rounds. A DC 17 Will save reduces this duration to 1 round. This is a mind-affecting effect."},{"type":"Misfortune","kind":"Su","details":"As a standard action that doesn't provoke an attack of opportunity, Malikadna can cause a creature within 30 ft. to suffer grave misfortune for 1 round. Anytime the creature makes an ability check, attack roll, saving throw, or skill check, it must roll twice and take the worse result. A DC 17 Will save negates this effect. A single creature cannot be targeted by this ability more than once per day. Witch's Familiar A witch forms a close bond with a familiar, a creature that teaches her magic and helps to guide her along her path. Instead of a spellbook, Malikadna must commune with her familiar each day to prepare her spells. A witch's familiar otherwise functions like the wizard's arcane bond class feature."}],"gear":"quarterstaff, wand of vampiric touch (8 charges)","before_combat":"Malikadna casts mage armor before entering into combat.","during_combat":"Malikadna prefers to avoid melee combat, instead using her spells and hexes to support the cannibals in a fight. If confronted on her own, she tries to use hideous laughter or cause fear to minimize attacks, but as soon as she takes damage, she uses her wand of vampiric touch to damage foes and heal her own damage.","morale":"Malikadna fights to the death.","source":"AP 37, Pathfinder RPG Advanced Player's Guide 65"},{"name":"Klorak the Red","cr":3,"xp":800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":3},{"class":"ranger","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":12,"ac_touch":10,"ac_flat_footed":10,"ac_mods":"+2 Dex, -2 rage, +2 shield","hp":48,"hd":"3d12+1d10+23","hd_value":4,"fort":9,"ref":5,"will":3,"defensive_abilities":["trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":45}],"melee":"+1 scimitar +10 (1d6+6/18-20), bite +4 (1d4+5)","ranged":"javelin +6 (1d6+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humans +2"},{"type":"rage","details":"10 rounds/day"},{"type":"rage powers","details":"animal fury"}],"strength":20,"dexterity":15,"constitution":18,"intelligence":8,"wisdom":10,"charisma":12,"baseatk":4,"cmb":9,"cmd":19,"feats":[{"feat":"Fleet"},{"feat":"Improved Initiative"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":8},{"skill":"Handle Animal","value":5},{"skill":"Intimidate","value":8},{"skill":"Perception","value":7},{"skill":"Survival","value":7},{"skill":"Swim","value":9}],"languages":["Pidgin Infernal"],"sq":["fast movement","track +1","wild empathy +2"],"gear":"heavy wooden shield, +1 scimitar, 5 javelins, red pearl amulet worth 500 gp","during_combat":"Klorak rages on the first round of combat and then charges the nearest foe, resorting to javelins only against foes who flee and can outrun him. Klorak is somewhat obsessed with blood, especially since one of Malikadna's many lies to him was that the blood of his enemies can increase his virility. The round after he first damages a foe, he attempts a touch attack (this action provokes an attack of opportunity and forces him to drop or sheath his scimitar) to gather the foe's blood on his palm so he can smear the blood across his chest and face, rolling his eyes and howling maniacally as he does so. He does this the same every round after he drops a foe into negative hit points. This tactic should help to make Klorak a memorable foe against the PCs as well as to give them a few moments of respite against the powerful enemy-if you find that the PCs are having little problem handling the dangerous barbarian, feel free to omit this behavior.","morale":"Klorak fights to the death.","base_statistics":"When not raging, Klorak's statistics are AC 14, touch 12, flat-footed 12; hp 42; Fort +7, Will +1; Melee +1 scimitar +8 (1d6+4/18-20), bite +2 (1d4+3); Str 16, Con 14; CMB +7; Skills Climb +6, Swim +7","source":"AP 37"},{"name":"Festrog","cr":1,"xp":400,"race":"Festrog","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","init":5,"senses":["darkvision 60 ft.","scent"],"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+1 Dex, +3 natural","hp":11,"hd":"2d8+2","hd_value":2,"fort":1,"ref":1,"will":4,"defensive_abilities":["diseased pustules"],"immunities":["undead traits"],"speed":[{"type":"land","speed":30,"special":"50 ft. on all fours"}],"melee":"2 claws +2 (1d4+1), bite +2 (1d4+1 plus feed and trip)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":13,"intelligence":10,"wisdom":12,"charisma":13,"baseatk":1,"cmb":2,"cmd":13,"cmd_special":"17 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Run"}],"skills":[{"skill":"Acrobatics","value":3},{"skill":"Perception","value":6},{"skill":"Stealth","value":6},{"skill":"Survival","value":3}],"languages":["Common"],"sq":["four-footed run"],"special_abilities":[{"type":"Diseased Pustules","kind":"Su","details":"A creature that damages a festrog with a slashing or piercing natural weapon, light weapon, or one-handed weapon is sprayed with foul, diseased pus from the creature's boils. The target must make a DC 12 Fortitude save or be sickened for 1d6 rounds from this effect. Anyone who becomes sickened from this effect is also exposed to filth fever (DC 12 Fortitude save negates). The save DC is Charisma-based."},{"type":"Feed","kind":"Su","details":"When a festrog inflicts bite damage on a living creature, the festrog feeds on the flesh and gains 5 temporary hit points."},{"type":"Four-Footed Run","kind":"Ex","details":"If a festrog doesn't hold or carry anything in its hands, it can run on all fours. This increases its speed to 50 ft. Festrogs gain Run as a bonus feat."}],"during_combat":"These foul undead quickly run forward on all fours to attack any living intruders.","morale":"The festrogs fight until destroyed.","source":"AP 37"},{"name":"Nylithati (Mother Thrunefang)","cr":4,"xp":1200,"race":"lacedon","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Ydersius","level":3}],"alignment":"CE","size":"Medium","type":"undead","init":3,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+2 deflection, +2 Dex, +3 natural","hp":45,"hd":"5d8+23","hd_value":5,"fort":6,"ref":4,"will":9,"defensive_abilities":["channel resistance +2"],"immunities":["undead traits"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"2 claws +6 (1d6+3 plus paralysis), bite +6 (1d6+3 plus disease and paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"6/day, DC 14, 2d6"},{"type":"disease","details":"DC 14"},{"type":"paralysis","details":"DC 14"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"6/day","spells":[{"spell":"inspiring word","details":"1 round"},{"spell":"touch of chaos"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":3,"spellsprepared_concentration":6,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"darkness"},{"spell":"enthrall","type":"domain"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cause fear"},{"spell":"divine favor","type":"domain"},{"spell":"obscuring mist"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"mending"}]}],"spelldomains":"Chaos, Nobility","strength":17,"dexterity":15,"intelligence":17,"wisdom":16,"charisma":16,"baseatk":3,"cmb":6,"cmd":20,"feats":[{"feat":"Combat Casting"},{"feat":"Command Undead"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Climb","value":8},{"skill":"Intimidate","value":9},{"skill":"Knowledge (arcana)","value":9},{"skill":"Knowledge (engineering)","value":6},{"skill":"Knowledge (nobility)","value":9},{"skill":"Knowledge (religion)","value":9},{"skill":"Perception","value":9},{"skill":"Stealth","value":8},{"skill":"Swim","value":19}],"languages":["Common","Abyssal","Infernal","Polyglot"],"gear":"amulet of natural armor +1, ring of swimming","before_combat":"Nylithati casts shield of faith on herself if she can before entering combat or responding to the sounds of battle in area V27.","during_combat":"Nylithati opens combat by casting darkness. She then lurks in the darkness while she casts spiritual weapon, cause fear, and finally divine favor before attacking. If outnumbered by more than three foes, she channels negative energy-she also uses channeled negative energy to heal her lacedon allies whenever one is damaged.","morale":"Nylithati fights until destroyed.","source":"AP 37, Pathfinder RPG Bestiary 146"}];
